# 02. 工具函数（安全类型转换）
# ============================================================

def safe_int(v, default=0) -> int:
    try:
        if v is None:
            return int(default)
        s = str(v).strip()
        if s == "":
            return int(default)
        return int(float(s))
    except Exception:
        return int(default)

def safe_float(v, default=0.0) -> float:
    try:
        if v is None:
            return float(default)
        s = str(v).strip()
        if s == "":
            return float(default)
        return float(s)
    except Exception:
        return float(default)

# ✅ 兼容旧命名：脚本其它地方仍可能在用 _safe_int / _safe_float
_safe_int = safe_int
_safe_float = safe_float

def safe_bool(v, default=False) -> bool:
    try:
        if isinstance(v, bool):
            return v
        if v is None:
            return bool(default)
        if isinstance(v, (int, float)):
            return bool(v)
        s = str(v).strip().lower()
        if not s:
            return bool(default)
        if s in {"1", "true", "yes", "y", "on", "enable", "enabled"}:
            return True
        if s in {"0", "false", "no", "n", "off", "disable", "disabled"}:
            return False
        return bool(default)
    except Exception:
        return bool(default)


_WEEKDAY_ZH = ["周一", "周二", "周三", "周四", "周五", "周六", "周日"]


def _current_system_time_info() -> Dict[str, str]:
    """
    每次调用都实时读取本机系统时间（含时区），用于“时间感知”注入。
    """
    try:
        now = datetime.datetime.now().astimezone()
    except Exception:
        now = datetime.datetime.now()

    try:
        weekday = _WEEKDAY_ZH[now.weekday()]
    except Exception:
        weekday = ""

    tz_name = ""
    try:
        tz_name = str(now.tzname() or "").strip()
    except Exception:
        tz_name = ""

    offset_raw = ""
    try:
        offset_raw = now.strftime("%z")  # 例如 +0800
    except Exception:
        offset_raw = ""
    if len(offset_raw) == 5 and (offset_raw.startswith("+") or offset_raw.startswith("-")):
        offset = f"{offset_raw[:3]}:{offset_raw[3:]}"  # +08:00
    else:
        offset = offset_raw

    return {
        "local_dt": now.strftime("%Y-%m-%d %H:%M:%S"),
        "iso": now.isoformat(timespec="seconds"),
        "date": now.strftime("%Y-%m-%d"),
        "time": now.strftime("%H:%M:%S"),
        "weekday": weekday,
        "tz_name": tz_name,
        "utc_offset": offset,
        "unix_ts": str(int(now.timestamp())),
    }


def _build_system_time_block() -> str:
    """
    给模型的“当前系统时间”上下文块。
    """
    t = _current_system_time_info()
    tz_display = t.get("tz_name", "")
    if t.get("utc_offset"):
        tz_display = f"{tz_display} (UTC{t['utc_offset']})".strip()

    return (
        "【当前系统时间】\n"
        f"- 本地时间: {t.get('local_dt', '')}\n"
        f"- 星期: {t.get('weekday', '')}\n"
        f"- 时区: {tz_display}\n"
        f"- ISO时间: {t.get('iso', '')}\n"
        f"- Unix时间戳: {t.get('unix_ts', '')}\n"
        "【时间使用规则】涉及“今天/明天/昨天/现在”等相对时间时，以上述系统时间为准。"
    )

