def format_unix_ts(ts: Any) -> str:
    sec = max(0, safe_int(ts, 0))
    if sec <= 0:
        return "-"
    try:
        return datetime.datetime.fromtimestamp(sec).strftime("%Y-%m-%d %H:%M:%S")
    except Exception:
        return "-"


